local q=table.concat(arg," "):lower(); if q=="" then print("Usage: inventory-find <term>") return end; for _,s in ipairs(peripheral.getNames()) do if peripheral.hasType(s,"inventory") then local p=peripheral.wrap(s); for slot,v in pairs(p.list()) do local d=p.getItemDetail(slot); if d and d.name:lower():find(q,1,true) then print(s.." slot "..slot.." "..d.name.." x"..d.count) end end end end
